import{$ as e,A as t,B as n,V as r}from"./chunks/framework.qypF2UUz.js";var i=JSON.parse(`{"title":"Logging","description":"","frontmatter":{},"headers":[],"relativePath":"docs/Logging.md","filePath":"docs/Logging.md"}`),a={name:`docs/Logging.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to “Logging”">​</a></h1><p>In this section we explain how the log subsystem is configured.</p><p>You configure the log in file application.yaml found in the resources folder of OAG. There the section <code>logging:</code> is relevant. This section is standard SpringBoot and you can find details about log configuration <a href="https://howtodoinjava.com/spring-boot2/logging/configure-logging-application-yml/" target="_blank" rel="noreferrer">for example here</a>.</p><p>One special thing we are using is the log-pattern. Here we apply <code>%X{oag.CorrId}</code>. This makes sure that the trace id (or correlation id) is written with each log statement. So make sure your log pattern contains <code>%X{oag.CorrId}</code> if you need log correlation - which we strongly recommend.</p><p>When it comes to log destinations we currently ship only what comes with SpringBoot out of the box.</p>`,5)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};